import Foundation
import Vapor

// File storage service with Unicode-aware path validation
struct FileStorageConfig {
    let baseDirectory: String
    let maxFileSize: Int
    let allowedExtensions: Set<String>

    static let `default` = FileStorageConfig(
        baseDirectory: "/var/app/uploads",
        maxFileSize: 10_485_760,
        allowedExtensions: ["txt", "pdf", "png", "jpg", "docx"]
    )
}

/// Normalizes a filename to prevent Unicode-based bypasses
/// Uses NFC (precomposed) form for consistent comparison
func normalizeFilename(_ input: String) -> String {
    // Strip any null bytes
    let cleaned = input.replacingOccurrences(of: "\0", with: "")
    // Normalize to NFC for consistent security checks
    return cleaned.precomposedStringWithCanonicalMapping
}

/// Validates that a resolved path stays within the allowed base directory
/// Returns the safe, resolved path or nil if traversal detected
func validatePath(filename: String, config: FileStorageConfig) -> String? {
    let normalized = normalizeFilename(filename)

    // Check for obvious traversal patterns in normalized form
    let traversalPatterns = ["..", "./", "//", "~"]
    for pattern in traversalPatterns {
        if normalized.contains(pattern) {
            return nil
        }
    }

    // Validate extension
    let ext = (normalized as NSString).pathExtension.lowercased()
    guard config.allowedExtensions.contains(ext) else {
        return nil
    }

    // Build the target path
    let targetPath = (config.baseDirectory as NSString).appendingPathComponent(normalized)

    // Resolve symlinks and relative components
    let resolvedPath = (targetPath as NSString).standardizingPath

    // Verify the resolved path is still under base directory
    guard resolvedPath.hasPrefix(config.baseDirectory) else {
        return nil
    }

    return resolvedPath
}

/// Writes file data to the validated path
/// IMPORTANT: The filesystem may interpret the filename differently
/// depending on the OS normalization form (HFS+ uses NFD)
func writeFile(data: Data, filename: String, config: FileStorageConfig) throws -> String {
    guard data.count <= config.maxFileSize else {
        throw Abort(.payloadTooLarge)
    }

    // Validate the path using NFC-normalized filename
    guard let safePath = validatePath(filename: filename, config: config) else {
        throw Abort(.badRequest, reason: "Invalid filename")
    }

    // Write using the original filename joined to base directory
    // The filesystem (HFS+/APFS) will normalize to NFD internally
    let actualWritePath = (config.baseDirectory as NSString)
        .appendingPathComponent(filename.decomposedStringWithCanonicalMapping)

    let actualResolved = (actualWritePath as NSString).standardizingPath

    // Create intermediate directories if needed
    let dir = (actualResolved as NSString).deletingLastPathComponent
    try FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)

    try data.write(to: URL(fileURLWithPath: actualResolved))
    return actualResolved
}

/// Route handler for file uploads
func configureRoutes(_ app: Application) throws {
    let config = FileStorageConfig.default

    app.post("upload") { req -> Response in
        guard let contentType = req.headers.contentType,
              contentType == .multipart else {
            throw Abort(.unsupportedMediaType)
        }

        let file = try req.content.decode(FileUpload.self)

        guard !file.filename.isEmpty else {
            throw Abort(.badRequest, reason: "Filename required")
        }

        let writtenPath = try writeFile(
            data: file.data,
            filename: file.filename,
            config: config
        )

        return Response(
            status: .created,
            body: .init(string: "{\"path\": \"\(writtenPath)\"}")
        )
    }

    app.get("files", ":name") { req -> Response in
        guard let name = req.parameters.get("name") else {
            throw Abort(.badRequest)
        }

        guard let safePath = validatePath(filename: name, config: config) else {
            throw Abort(.notFound)
        }

        guard FileManager.default.fileExists(atPath: safePath) else {
            throw Abort(.notFound)
        }

        let data = try Data(contentsOf: URL(fileURLWithPath: safePath))
        return Response(status: .ok, body: .init(data: data))
    }
}

struct FileUpload: Content {
    let filename: String
    let data: Data
}
